#!/usr/bin/env python3
"""Unfitted whole native/actual Metal Invisible501-tick lifecycle panels."""
import argparse,json
from pathlib import Path
from PIL import Image,ImageDraw
from speed_profile_contract import sha
SELECTED=(1,6,16,30,35,40,100,430,431,432,459,461,480,499,500,501)
def run(native,metal,output):
 output.mkdir(parents=True,exist_ok=False);n=json.loads((native/'manifest.json').read_text());m=json.loads((metal/'manifest.json').read_text());assert n['status']=='bounded_native_preflight'and m['status']=='pass';assert len(m['frames'])==501 and m['sample_simulation_ticks']==list(range(1,502));assert n['configuration']['viewport']==m['scenario']['resolution']==[640,480];whole=Image.new('RGB',(1280,len(SELECTED)*505));crop=Image.new('RGB',(320,len(SELECTED)*185));w=ImageDraw.Draw(whole);c=ImageDraw.Draw(crop);pairs=[];maximum=0
 for row,tick in enumerate(SELECTED):
  r=n['rows'][tick-1];paths=[Path(r['image']),Path(m['frames'][tick-1]['path'])];hashes=[r['image_sha256'],m['frames'][tick-1]['sha256']];assert[sha(p.read_bytes())for p in paths]==hashes;images=[Image.open(p).convert('RGB')for p in paths];bounds=[d['projected_geometry_bounds']for d in r['draws']];assert all(0<=b[0]<=b[2]<640 and 0<=b[1]<=b[3]<480 for b in bounds);visible=[im.getbbox()for im in images];assert all(bool(v)==bool(visible[0])for v in visible)
  delta=max(abs(a-b)for a,b in zip(*visible))if visible[0]else 0;maximum=max(maximum,delta);pairs.append(dict(tick=tick,owner_frame=r['frame'],life=r['life'],owner_flags=r['owner_flags'],draw_count=len(r['draws']),images=list(map(str,paths)),sha256=hashes,visible_bbox=visible,bbox_max_edge_difference=delta,all_geometry_inside_viewport=True,draw_geometry_bounds=bounds,blank=not visible[0]))
  for col,(im,label)in enumerate(zip(images,('Original','Actual Metal'))):whole.paste(im,(col*640,row*505+25));w.text((col*640+4,row*505+5),f'{label} Invisible tick{tick}',fill='white');crop.paste(im.crop((240,130,400,290)),(col*160,row*185+25));c.text((col*160+4,row*185+5),f'{label} tick{tick}',fill='white')
 whole.save(output/'whole.png');crop.save(output/'fixed-crop.png');r=dict(status='awaiting_independent_review',accepted=False,type_id='0xad92bc16',asset_sha256=n['asset_sha256'],binary_sha256=m['binary_sha256'],native_manifest_sha256=sha((native/'manifest.json').read_bytes()),metal_manifest_sha256=sha((metal/'manifest.json').read_bytes()),whole_sha256=sha((output/'whole.png').read_bytes()),fixed_crop_sha256=sha((output/'fixed-crop.png').read_bytes()),pairs=pairs,actual_frames=501,pixel_summary={k:v for k,v in m['pixel_summary'].items()if k!='pixel_sha256'},configuration=m['scenario'],appearance_fitted=False,max_bbox_edge_difference=maximum,scope='Exact Invisible original own500tick owner/custom6rings/70particles/complete wholeRender vs actual Metal501frames. Hide→WAIT35/blank100,430→SHOW431→blank499 and realkill500/blank501. All geometry inside declared640x480 with same explicitcenter320,240 and fixed actualsizecrop240,130,400,290. No fittedcamera/phase/geometry/color/lighting. Native null-invoker ring translatedownerdouble-position quirk preserved; natural actorfade/status/audio, original generalobject constructor, normalmap/device, otherlighting/sampling/exactpixels remain open.');(output/'manifest.json').write_text(json.dumps(r,indent=2)+'\n');print(r['status'],r['pixel_summary'],maximum);return r
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--native',type=Path,required=True);p.add_argument('--metal',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();run(a.native,a.metal,a.output)
